// Presentation only. Calculations and actions remain in the existing workflow modules.
import {summary, nextAction} from './workflow.js';

export function renderWelcome({icon, btn}) {
  const samples = [
    ['repair', 'Dokumen perlu diperbaiki', 'Perjelas dokumenmu.', 'Foto dokumen belum terbaca. Pastikan seluruh halaman terlihat sebelum dikirim kembali.', 'Catatan pemeriksaan', 'Perlu perbaikan', 'red'],
    ['sent', 'Dikirim kembali', 'Sekarang, giliran petugas.', 'Dokumen perbaikan sudah diterima untuk diperiksa. Calon mahasiswa dapat memantau perkembangannya.', 'Bukti pengajuan', 'Menunggu verifikasi', 'blue'],
    ['verified', 'Diverifikasi petugas', 'Satu kewajiban dituntaskan.', 'Petugas menyatakan dokumen sesuai. Status persyaratan diperbarui dan langkah berikutnya menjadi lebih jelas.', 'Hasil pemeriksaan', 'Selesai', 'green']
  ];
  return `<div class="landing campus-landing"><header class="landing-header"><a href="#welcome" class="landing-brand">${icon('leaf')}ADMIRA<span>Setiap tahap, ada tindak lanjut.</span></a><div class="landing-header-right"><span class="edition-label">PERJALANAN MENUJU KAMPUS</span><span class="live-mark">Data simulasi</span></div></header>
  <main id="main" class="landing-main" tabindex="-1"><section class="campus-hero"><div class="campus-hero-copy"><span class="eyebrow">ADMISI <b>•</b> REGISTRASI <b>•</b> PENDAMPINGAN</span><h1>Langkah Menuju<br>Kuliah, <em>Lebih<br>Terarah.</em></h1><p>Dari persyaratan pertama sampai langkah berikutnya. Ketahui posisimu, selesaikan kewajiban, dan temukan bantuan yang tepat.</p><div class="campus-hero-actions"><button class="btn apricot" data-role="student">Coba Demo Calon Mahasiswa ${icon('arrow')}</button><button class="text-btn" data-role="staff">Masuk ke Demo Petugas ${icon('arrow')}</button></div><p class="campus-demo-note">${icon('shield')} Prototipe interaktif dengan data latihan.<br>Belum memakai akun atau autentikasi sungguhan.</p></div>
  <div class="campus-specimen" aria-label="Pratinjau perjalanan pendaftaran dengan data simulasi"><div class="specimen-caption"><span>SEBUAH PERJALANAN, BUKAN SEKADAR STATUS.</span><span>01 — 05</span></div><div class="journey-pass"><div class="journey-pass-head"><div><span class="eyebrow">BERKAS PERJALANAN</span><strong>Calon mahasiswa</strong><small>Contoh tampilan · bukan pendaftaran nyata</small></div>${icon('book')}</div><ol class="specimen-stages">${[['Pendaftaran','Selesai'],['Seleksi','Selesai'],['Pengumuman','Selesai'],['Daftar ulang','Perlu tindakan'],['Aktivasi mahasiswa','Belum dibuka']].map(([name,status],i)=>`<li class="${i<3?'is-done':i===3?'is-current':'is-upcoming'}"><span>${i<3?icon('check'):'0'+(i+1)}</span><div><strong>${name}</strong><small>${status}</small></div>${i===3?icon('arrow'):''}</li>`).join('')}</ol><div class="pass-foot"><span>TAHAP SAAT INI</span><strong>04 / Daftar ulang</strong></div></div><div class="specimen-note"><span class="specimen-note-icon">${icon('file')}</span><div><span>CATATAN PEMERIKSAAN · CONTOH</span><strong>Dokumen kelulusan</strong><p>Pastikan seluruh halaman terbaca.</p></div><span class="note-mark">!</span></div><div class="specimen-deadline">${icon('calendar')}<div><small>TENGGAT SIMULASI</small><strong>30 Oktober · 16.00 WIB</strong></div><span>04</span></div></div></section>
  <section class="campus-proof"><div class="campus-section-heading"><div><span class="eyebrow">SATU DOKUMEN. TINDAK LANJUT YANG JELAS.</span><h2>Setiap perubahan,<br><em>ada arahnya.</em></h2></div><p>Lihat bagaimana catatan petugas menjadi tindakan dan bukti penyelesaian. Pilih tahap untuk melihat contoh tampilannya.</p></div><fieldset class="proof-demo"><legend class="mini-chat-sr">Tahap contoh pemeriksaan dokumen</legend><div class="proof-tabs">${samples.map(([id,label],i)=>`<div><input type="radio" name="proof-stage" id="proof-${id}" ${i===0?'checked':''}><label for="proof-${id}"><span>0${i+1}</span><strong>${label}</strong>${icon('arrow')}</label></div>`).join('')}</div><div class="proof-panels">${samples.map(([id,label,title,text,kicker,status,color])=>`<section class="proof-panel proof-${id}" aria-label="Contoh: ${label}"><div class="proof-document">${icon('file')}<span>DOKUMEN KELULUSAN</span><strong>Dokumen contoh.pdf</strong><span class="pill ${color}">${status}</span><small>ILUSTRASI · DATA SIMULASI</small></div><div class="proof-explanation"><span class="eyebrow">${kicker}</span><h3>${title}</h3><p>${text}</p></div></section>`).join('')}</div></fieldset></section>
  <section class="campus-roles"><div><span class="eyebrow">DUA RUANG. SATU PERJALANAN.</span><h2>Kamu tahu langkahnya.<br>Petugas tahu <em>tindak lanjutnya.</em></h2></div><div class="campus-role-notes"><p><span>01 / CALON MAHASISWA</span>Persyaratan, tenggat, catatan pemeriksaan, dan bantuan dalam satu perjalanan.</p><p><span>02 / PETUGAS</span>Tinjau kasus, periksa berkas, tangani kendala, dan evaluasi layanan dari data latihan yang sama.</p>${btn('Kenali ADMIRA','guide','secondary','book')}</div></section><footer class="landing-footer"><span>ADMIRA · Setiap tahap, ada tindak lanjut.</span><span>Prototipe penerimaan mahasiswa / Data simulasi</span></footer></main><button class="chat-launcher" data-action="chat-open" aria-label="Tanya ADMIRA" aria-haspopup="dialog" aria-controls="admira-mini-chat">${icon('help')}<span>Tanya ADMIRA</span></button></div>`;
}

export function renderOperations(k) {
  const {state, filters, esc, icon, btn, filterbar, casesTable, fmt} = k;
  const data = summary(state, {year:filters.year, route:filters.route, prodi:filters.prodi, region:filters.region});
  const m = data.counts, cases = data.rows;
  const pending = cases.filter(c=>['Perlu tindakan','Perlu perbaikan'].includes(c.status));
  const review = cases.filter(c=>c.status==='Menunggu verifikasi');
  const queue = [...pending, ...review].sort((a,b)=>new Date(a.deadline||'2099-01-01')-new Date(b.deadline||'2099-01-01'));
  const ratio = m.accepted ? Math.round(m.registered/m.accepted*100) : null;
  const amounts = [m.total,m.accepted,m.registered,m.active], denominators = [m.total,m.final,m.accepted,m.registered];
  const available=state.sessions.filter(s=>s.status==='Terjadwal'&&new Date(s.date)>new Date(state.now)).reduce((n,s)=>n+Math.max(0,s.capacity-s.bookings.length),0);
  return `<div class="desk-heading"><div><span class="eyebrow">RUANG KERJA PENERIMAAN / ${esc(state.module).toUpperCase()}</span><h1>Penerimaan ${esc(filters.year||'semua periode')}<span>.</span></h1><p>Gambaran perjalanan, daftar pekerjaan, dan tindak lanjut layanan.</p></div><div class="desk-heading-actions"><span class="live-mark">Data latihan</span>${btn('Ekspor ringkasan','export-summary','secondary','download')}</div></div>
  <div class="desk-filterbar">${filterbar()}</div>
  <section class="desk-metrics" aria-label="Ringkasan terhubung">${data.tiles.map((t,i)=>`<button class="desk-metric ${i===0?'desk-metric-main':''}" data-metric="${t.id}"><span class="desk-metric-label">${t.title}${icon('arrow')}</span><strong>${t.value===null?'—':t.value}</strong><span>${t.unit==='tiket'?t.applications+' aplikasi terkait':t.value===null?'Pengenal orang belum lengkap':t.applications+' aplikasi · orang unik'}</span><small>Buka rincian</small></button>`).join('')}</section>
  <p class="count-definition">${data.people===null?'Jumlah orang belum dapat dipastikan.':`${data.people} pendaftar unik dari ${m.total} aplikasi berdasarkan ID orang pada dataset demo.`} Kategori bertumpang tindih; tidak dijumlahkan.</p>
  <div class="desk-analysis"><section class="desk-flow"><div class="desk-section-title"><div><span class="eyebrow">01 / ALUR PENERIMAAN</span><h2>Dari mendaftar, sampai aktif.</h2></div><span class="flow-scope">Unit: aplikasi</span></div>${m.total?`<div class="desk-pipeline">${['Pendaftaran','Diterima','Daftar ulang','Mahasiswa aktif'].map((name,i)=>`<button data-metric="${['total','accepted','registered','active'][i]}" class="desk-pipeline-row"><span class="desk-pipeline-name"><small>0${i+1}</small>${name}</span><span class="desk-pipeline-track"><span class="desk-pipeline-fill flow-${i}" style="width:${amounts[i]/m.total*100}%"></span><strong>${amounts[i]}</strong></span><span class="desk-pipeline-ratio">${denominators[i]?Math.round(amounts[i]/denominators[i]*100)+'%':'—'}<small>${amounts[i]}/${denominators[i]}</small></span><span class="desk-pipeline-basis">${['seluruh aplikasi','hasil seleksi final','diterima pada tahap daftar ulang','selesai daftar ulang'][i]}</span></button>`).join('')}</div>`:`<div class="empty"><h3>Belum ada data pada cakupan ini.</h3><p>Ubah filter untuk meninjau pendaftaran lainnya.</p></div>`}<div class="desk-flow-note"><span><i></i> Panjang batang: proporsi dari ${m.total} aplikasi</span><span>Rasio setiap tahap memakai penyebut tertulis.</span></div></section>
  <aside class="desk-work"><div class="desk-work-title"><span class="eyebrow">FOKUS PEKERJAAN</span>${icon('tasks')}</div><div class="desk-work-total"><strong>${pending.length}</strong><span>pendaftaran<br>perlu tindakan</span></div><div class="desk-work-list"><div><span>Menunggu pemeriksaan</span><strong>${review.length}</strong></div><div><span>Tiket belum selesai</span><strong>${data.tickets.length}</strong></div><div><span>Melewati tenggat</span><strong>${data.passed}</strong></div></div>${btn('Buka antrean tindak lanjut','goto-followup','','arrow')}<p>Tinjau berkas dan kendala sebelum mengirim pengingat.</p></aside></div>
  <div class="desk-period"><span class="desk-period-mark">${icon('clock')}</span><p><strong>Periode masih berjalan.</strong> ${data.ongoing} diterima belum selesai daftar ulang dan masih dalam jadwal atau belum memiliki tenggat. ${data.passed} melewati tenggat dan perlu ditinjau; tidak otomatis dibatalkan.</p><div><strong>${ratio===null?'—':ratio+'%'}</strong><small>${m.registered}/${m.accepted} diterima telah daftar ulang</small></div></div>
  <section class="panel queue-panel desk-queue"><div class="desk-section-title"><div><span class="eyebrow">02 / ANTREAN TINDAK LANJUT</span><h2>Langkah yang menunggu Anda.</h2><p>Urutan tenggat terdekat. Pilih calon mahasiswa untuk meninjau kasus.</p></div><button class="text-btn" data-page="followup">Semua antrean ${icon('arrow')}</button></div>${casesTable(queue,4)}<div class="table-footer"><span>${Math.min(4,queue.length)} dari ${queue.length} kasus ditampilkan</span><span>Sumber: data latihan ADMIRA</span></div></section>
  <div class="desk-services"><button data-action="tickets"><span>${icon('help')} BANTUAN</span><strong>${data.tickets.length} tiket terbuka</strong><small>Tinjau kebutuhan peserta ${icon('arrow')}</small></button><button data-page="programs"><span>${icon('calendar')} PENDAMPINGAN</span><strong>${available} slot konsultasi</strong><small>Kelola sesi dan kegiatan ${icon('arrow')}</small></button><button data-page="data"><span>${icon('data')} LANDASAN ANALISIS</span><strong>Data yang dapat ditelusuri</strong><small>Periksa sumber dan versinya ${icon('arrow')}</small></button></div>
  <section class="desk-evaluation"><div><span class="eyebrow">03 / DARI TEMUAN KE PERBAIKAN</span><h2>Buktinya jelas.<br><em>Tindak lanjutnya terarah.</em></h2><p>Tinjau dasar rekomendasi, tetapkan pelaksana, dan catat hasil evaluasi.</p></div><button class="btn apricot" data-page="evaluation">Evaluasi & Rekomendasi ${icon('arrow')}</button></section>
  <section class="module-showcase desk-modules"><div><span class="eyebrow">ENAM RUANG TINDAKAN</span><h2>Pendampingan yang terhubung.</h2></div><div class="module-chips">${[['Alur','tasks'],['Akses','users'],['Prodi','book'],['Siklus','refresh'],['Jangkauan','map'],['Mutu Data','data']].map(([name,i])=>`<button data-module="${name}" class="${state.module===name?'selected':''}">${icon(i)}${name}</button>`).join('')}</div></section>`;
}

export function renderCandidate(k) {
  const {state,c,btn,icon,esc,pill,fmt,journeyMarkup} = k;
  const next=nextAction(state,c.id), waiting=c.status==='Menunggu verifikasi', done=['Aktif','Daftar ulang selesai'].includes(c.source);
  const tone=waiting?'waiting':done?'complete':'action';
  return `<div class="candidate-heading"><div><span class="eyebrow">PERJALANAN MENUJU KAMPUS / ${esc(c.year)}</span><h1>Halo, ${esc(c.name.split(' ')[0])}<span>.</span></h1><p>Setiap langkahmu, semakin terarah.</p></div><span class="live-mark">Data latihan</span></div>
  <div class="candidate-workspace"><div class="candidate-main"><section class="candidate-action tone-${tone}"><div class="candidate-action-meta"><span class="eyebrow">LANGKAH BERIKUTNYA</span>${pill(c.status)}</div><div class="candidate-action-copy"><span class="action-document-number">${icon(waiting?'clock':done?'check':'file')}</span><div><h2>${esc(next.title)}</h2><p>${esc(next.text)}</p></div></div><div class="candidate-action-deadline">${icon('calendar')}<span><small>TENGGAT SIMULASI</small>${fmt(c.deadline)}</span></div><div class="actions">${btn(next.button,next.action,'','arrow')}${btn('Saya butuh bantuan','new-ticket','secondary','help')}</div><p class="candidate-source">${icon('shield')} Status sumber: ${esc(c.source)} · diperbarui ${fmt(state.updatedAt,false)}</p></section>
  <section class="panel candidate-journey"><div class="desk-section-title"><div><span class="eyebrow">01 / JEJAK LANGKAHMU</span><h2>Perjalanan pendaftaran</h2></div><button class="text-btn" data-page="journey" aria-label="Lihat rincian perjalanan">Rincian ${icon('arrow')}</button></div>${journeyMarkup(c)}<p class="candidate-journey-note">Setiap penyelesaian mengikuti hasil verifikasi.</p></section>
  <section class="panel candidate-documents"><div class="desk-section-title"><div><span class="eyebrow">02 / BERKAS PENDAFTARAN</span><h2>Persyaratanmu</h2></div><button class="text-btn" data-page="journey">Lihat semua ${icon('arrow')}</button></div>${c.requirements.filter(r=>r.applicable).map(r=>`<div class="candidate-document"><span class="candidate-document-icon">${icon('file')}</span><div><strong>${esc(r.name)}</strong><p>${esc(r.reason|| (r.status==='Menunggu verifikasi'?'Berkas sudah dikirim, menunggu pemeriksaan.':r.status==='Selesai'?'Persyaratan sudah diverifikasi petugas.':'Lengkapi berkas pada Langkah saya.'))}</p></div>${pill(r.status)}</div>`).join('')}</section></div>
  <aside class="candidate-aside"><section class="candidate-pass"><div class="candidate-pass-label"><span>BERKAS PERJALANAN</span>${icon('book')}</div><span class="candidate-pass-id">${esc(c.id)}</span><h2>${esc(c.name)}</h2><p>${esc(c.prodi)}<br>Jalur ${esc(c.route||'belum tersedia')}</p><div class="candidate-pass-status"><small>STATUS PENDAFTARAN</small>${pill(c.source)}</div><div class="candidate-pass-deadline">${icon('calendar')}<div><small>TENGGAT SIMULASI</small><strong>${fmt(c.deadline)}</strong></div></div></section>
  <section class="candidate-help"><span class="eyebrow">ADA PENDAMPING DI SETIAP LANGKAH</span><h2>Butuh teman<br><em>menemukan arah?</em></h2><p>Temukan sesi konsultasi atau ceritakan kendalamu melalui tiket bantuan.</p><button class="text-btn" data-page="sessions">Temukan sesi konsultasi ${icon('arrow')}</button></section><section class="candidate-guide"><span>${icon('file')} PANDUAN YANG BISA DIBAWA</span><p>Simpan checklist dan panduan ringkas untuk menemani prosesmu.</p><button class="text-btn" data-action="print-guide">Unduh panduan cetak ${icon('download')}</button></section></aside></div><div class="context-bar"><span>${icon('info')} Ruang simulasi. Semua identitas, jadwal, dan persyaratan adalah contoh latihan.</span></div>`;
}
